        var mode = Mode.Normal;
        var symbol = ' ';
        while (i < ss.length) {
            if (mode == Mode.Normal) {
                if (ss[i] >= '0' && ss[i] <= '9') {
                    num += String.valueOf(ss[i]);
                    if (++i == ss.length) {
                        stack.push(num);
                    }
                    continue;
                }

                if (num.length() > 0) {
                    stack.push(num);
                    num = "";
                }

                if (ss[i] == '+' || ss[i] == '-') {
                    stack.push(String.valueOf(ss[i]));
                }

                if (ss[i] == '*' || ss[i] == '/') {
                    symbol = ss[i];
                    mode = Mode.MultiplicationAndDivision;
                }

                i++;
            } else if (mode == Mode.MultiplicationAndDivision) {
                if (ss[i] >= '0' && ss[i] <= '9') {
                    num += String.valueOf(ss[i]);
                    if (++i < ss.length) {
                        continue;
                    }
                }

                if (num.length() > 0) {
                    if (symbol == '*') {
                        stack.push("" + Integer.parseInt(stack.pop()) * Integer.parseInt(num));
                    } else {
                        stack.push("" + Integer.parseInt(stack.pop()) / Integer.parseInt(num));
                    }
                    num = "";
                    mode = Mode.Normal;
                } else {
                    i++;
                }
            }
        }

        var result = 0;
        num = "0";
        while (!stack.isEmpty()) {
            var val = stack.pop();
            if (val.equals("+")) {
                result += Integer.parseInt(num);
            } else if (val.equals("-")) {
                result -= Integer.parseInt(num);
            } else {
                num = val;
            }
        }
        result += Integer.parseInt(num);

        return result;
    }
}

